import {escape as e,safeURL,slugify} from './ui.js';
import {sanitizeRichHTML,plainToHTML} from './richtext.js';
let assets=[],documents=[],removedDocuments=new Set(),pending=0;
const styles=['editorial','tutorial','field-notes'];
export function linkFields(x,key){return `<section class="full link-studio"><h3>Your branded link</h3><label class="field">Custom URL ending<input name="slug" maxlength="100" value="${e(x.slug||'')}" placeholder="Generated from the title"></label><p class="status">Use your own short, memorable name. The current website domain is used automatically.</p><output id="link-preview"></output><button class="text-link" type="button" id="copy-content-link">Copy link ↗</button></section>`;}
export function setupLinks(key){const f=document.querySelector('#editor-form'),slug=f.elements.slug,title=f.elements.title;let auto=!slug.value;function show(){if(auto)slug.value=slugify(title.value);document.querySelector('#link-preview').textContent=location.origin+(key==='courses'?'/learn/':'/read/')+slugify(slug.value||title.value);}
 title.addEventListener('input',show);slug.addEventListener('input',()=>{auto=!slug.value;show();});document.querySelector('#copy-content-link').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#link-preview').textContent);document.querySelector('#editor-status').textContent='Link copied. It becomes available after publishing.';}catch{document.querySelector('#editor-status').textContent='Select and copy the link shown above.';}};show();}
export function assetFields(x,key){return `<section class="full asset-studio"><h3>${key==='courses'?'Course image gallery':'Announcement images'}</h3><p class="status">${key==='courses'?'Add up to 8 images. Select the cover to choose the first image.':'Add up to 2 images for the Lookbook or Studio Gallery design.'} JPG, PNG or WebP; images are resized before upload.</p><label class="field">Upload images<input id="asset-upload" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><label class="field">Or add an existing image URL<input id="asset-url" type="url" placeholder="https://…"></label><button class="btn outline small" type="button" id="asset-add">Add image URL</button><div id="asset-list" class="asset-list"></div></section>`;}
export function setupAssets(x,key){for(const a of assets)if(a.file)URL.revokeObjectURL(a.url);assets=[...new Set([...(key==='courses'&&x.image?[x.image]:[]),...(x.images||[])])].map(url=>({url}));const limit=key==='courses'?8:2;function render(){document.querySelector('#asset-list').innerHTML=assets.map((a,i)=>`<div class="asset-card"><img src="${e((a.file?a.url:safeURL(a.url,{image:true})))}" alt="Image ${i+1}"><button type="button" data-cover="${i}" class="text-link">${i===0?'✓ Cover / first':'Make cover'}</button><button type="button" data-remove-asset="${i}" aria-label="Remove image ${i+1}">Remove</button></div>`).join('');document.querySelector('#editor-form').dispatchEvent(new Event('input'));}
 document.querySelector('#asset-list').onclick=event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.cover!==undefined){const [a]=assets.splice(Number(b.dataset.cover),1);assets.unshift(a);}if(b.dataset.removeAsset!==undefined){const [a]=assets.splice(Number(b.dataset.removeAsset),1);if(a.file)URL.revokeObjectURL(a.url);}render();};
 document.querySelector('#asset-upload').onchange=async event=>{const selected=[...event.target.files];if(assets.length+selected.length>limit){document.querySelector('#editor-status').textContent=`Choose up to ${limit} images in total.`;return;}pending++;try{for(const file of selected){const resized=await resizeImage(file);assets.push({file:resized,url:URL.createObjectURL(resized)});}render();}catch(err){document.querySelector('#editor-status').textContent=err.message;}pending--;event.target.value='';};
 document.querySelector('#asset-add').onclick=()=>{const f=document.querySelector('#asset-url'),raw=f.value.trim();try{const u=new URL(raw,location.origin);if(u.protocol!=='https:'&&u.origin!==location.origin)throw new Error();if(!raw||assets.length>=limit)throw new Error();assets.push({url:u.href});f.value='';render();}catch{document.querySelector('#editor-status').textContent=`Use a local or HTTPS image URL; maximum ${limit} images.`;}};render();}
export async function resizeImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error('Choose JPG, PNG or WebP images up to 5 MB each.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.84));if(!blob)throw new Error('Could not process this image.');return new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:blob.type});}finally{URL.revokeObjectURL(url);}}
export function articleTools(x){documents=x.attachments||[];removedDocuments=new Set();return `<section class="full document-studio"><h3>Start with a document</h3><p class="status">Import DOCX, TXT or HTML into the editable article. PDF, DOCX and TXT files can also be attached for readers to download (10 MB each, up to 5). PDF attachments are not converted to editable text. Uploaded attachments are public; use documents intended for readers.</p><label class="field">Import article text<input type="file" id="article-import" accept=".docx,.txt,.html,.htm"></label><p id="import-status" class="status" role="status"></p><label class="field">Attach documents<input type="file" id="article-documents" multiple accept=".pdf,.docx,.txt"></label><div id="document-list"></div><label class="field">Blog layout<select name="articleStyle">${styles.map(s=>`<option value="${s}" ${x.articleStyle===s?'selected':''}>${s.replace('-',' ')}</option>`).join('')}</select></label><label class="field">Starter outline<select id="article-outline"><option value="">Keep my text</option><option value="tutorial">Step by step tutorial</option><option value="story">Studio story</option><option value="checklist">Practical checklist</option></select></label><p class="status">Starter outlines insert at the end of your text, preserving your writing.</p></section>`;}
export function setupArticleTools(){const style=document.querySelector('[name=articleStyle]');const applyStyle=()=>{const composer=document.querySelector('.rich-composer');if(!composer)return;composer.classList.remove('article-editorial','article-tutorial','article-field-notes');composer.classList.add('article-'+style.value);};style.addEventListener('change',applyStyle);applyStyle();function render(){document.querySelector('#document-list').innerHTML=documents.filter((_,i)=>!removedDocuments.has(i)).map(a=>`<p>${e(a.name)} <button class="text-link" type="button" data-remove-document="${documents.indexOf(a)}">Remove</button></p>`).join('');}render();document.querySelector('#document-list').onclick=event=>{const b=event.target.closest('[data-remove-document]');if(b){removedDocuments.add(Number(b.dataset.removeDocument));render();}};
 document.querySelector('#article-documents').onchange=event=>{const files=[...event.target.files];if(documents.filter((_,i)=>!removedDocuments.has(i)).length+files.length>5){document.querySelector('#import-status').textContent='Attach up to 5 documents.';event.target.value='';return;}for(const file of files)documents.push({name:file.name,file});render();event.target.value='';};
 document.querySelector('#article-import').onchange=async event=>{const file=event.target.files[0],status=document.querySelector('#import-status');if(!file)return;pending++;try{if(file.size>10*1024*1024)throw new Error('Import a document up to 10 MB.');status.textContent='Reading your document…';let html;const ext=file.name.split('.').pop().toLowerCase();if(ext==='docx'){html=await convertDocx(await file.arrayBuffer());}else if(['html','htm','txt'].includes(ext)){const text=await file.text();html=ext==='txt'?plainToHTML(text):text;}else throw new Error('Import DOCX, TXT or HTML.');const clean=sanitizeRichHTML(html),box=document.querySelector('#rich-document');const probe=document.createElement('div');probe.innerHTML=clean;if(probe.textContent.length+box.textContent.length>20000)throw new Error('Article limit is 20,000 characters; shorten this document first.');if(!probe.textContent.trim())throw new Error('No readable text was found.');box.insertAdjacentHTML('beforeend',clean);box.dispatchEvent(new Event('input'));status.textContent='Imported below your existing text. Review the formatting before saving.';}catch(err){status.textContent=err.message;}pending--;event.target.value='';};
 const outlines={tutorial:'<h2>What you will learn</h2><p><br></p><h2>Before you begin</h2><ul><li><br></li></ul><h2>Step 1: Prepare</h2><p><br></p><h2>Step 2: Make</h2><p><br></p><h2>Your next step</h2><p><br></p>',story:'<h2>Inside the studio</h2><p><br></p><blockquote><br></blockquote><h2>The detail that matters</h2><p><br></p><h2>Take it into your practice</h2><p><br></p>',checklist:'<h2>Your practical checklist</h2><p><br></p><ul><li><br></li><li><br></li><li><br></li></ul><h2>A note from Gracy</h2><p><br></p>'};document.querySelector('#article-outline').onchange=event=>{if(outlines[event.target.value]){const box=document.querySelector('#rich-document');box.insertAdjacentHTML('beforeend',outlines[event.target.value]);box.dispatchEvent(new Event('input'));}event.target.value='';};}
function convertDocx(buffer){return new Promise((resolve,reject)=>{const worker=new Worker('/docx-worker.js');const timer=setTimeout(()=>{worker.terminate();reject(new Error('This document took too long to import. Try a smaller DOCX or TXT file.'));},20000);function finish(){clearTimeout(timer);worker.terminate();}worker.onmessage=event=>{finish();event.data.error?reject(new Error(event.data.error)):resolve(event.data.html);};worker.onerror=()=>{finish();reject(new Error('The DOCX importer could not read this file. Try exporting it as TXT.'));};worker.postMessage(buffer,[buffer]);});}
export async function collectAssets(v,key,backend){if(pending)throw new Error('Please wait for your images or document to finish processing.');if(['courses','popups'].includes(key)){const uploaded=[];for(const asset of assets){if(asset.file){uploaded.push(await backend.upload(asset.file,key==='courses'?'classes':'popups'));}else uploaded.push(asset.url);}v.images=uploaded;if(key==='courses'&&uploaded.length)v.image=uploaded[0];if(key==='popups'&&['lookbook','gallery'].includes(v.design)&&!uploaded.length)throw new Error('Add at least one image for this design.');}
 if(key==='posts'){const attachments=[];for(const [i,a] of documents.entries()){if(removedDocuments.has(i))continue;if(a.file){attachments.push(await backend.uploadDocument(a.file));}else attachments.push(a);}v.attachments=attachments;if(!styles.includes(v.articleStyle))v.articleStyle='editorial';}}
